-- FAQ แชทบอทภาษาอังกฤษ (จาก chatbot_service_faqs.xlsx) — ใช้แทน php artisan migrate ได้
-- จับคู่ตาม id 1-45 (ลำดับเดียวกับไฟล์) และไม่ทับค่าที่กรอกไว้แล้ว

ALTER TABLE `chatbot_service_faqs`
  ADD COLUMN IF NOT EXISTS `question_en` VARCHAR(255) NULL AFTER `question_th`,
  ADD COLUMN IF NOT EXISTS `answer_en` LONGTEXT NULL AFTER `answer_th`;

UPDATE `chatbot_service_faqs` SET `question_en` = COALESCE(NULLIF(`question_en`, ''), 'The Alarm Sounds Without an Emergency (Burglar Alarm System)'), `answer_en` = COALESCE(NULLIF(`answer_en`, ''), 'Please perform the following preliminary checks:
1. Check whether rats or ants have damaged the wiring or built nests inside the device.
2. Check for water leaks or dripping water onto the device.
3. Check whether the device or its wiring has been damaged by impact, tampering, or attempted forced entry.
If you identify any issues, please contact our support team or submit a repair request') WHERE `id` = 1; -- สัญญาณเตือนร้องขึ้นมาโดยไม่ทราบสาเหตุ (สัญญาณกันขโมย)
