UPDATE `chatbot_service_faqs` SET `question_en` = COALESCE(NULLIF(`question_en`, ''), 'What is the warranty period for the equipment?'), `answer_en` = COALESCE(NULLIF(`answer_en`, ''), 'Our alarm equipment comes with a warranty of up to 36 months. Based on our records, many customers have been using our equipment for over 30 years without experiencing any operational issues.') WHERE `id` = 4; -- ระยะเวลาในการคุ้มครองอุปกรณ์
UPDATE `chatbot_service_faqs` SET `question_en` = COALESCE(NULLIF(`question_en`, ''), 'The Alarm Sounds Without an Emergency (Fire Alarm System)'), `answer_en` = COALESCE(NULLIF(`answer_en`, ''), 'Please perform the following preliminary checks:
