UPDATE `chatbot_service_faqs` SET `question_en` = COALESCE(NULLIF(`question_en`, ''), 'What is the maximum insurance coverage limit?'), `answer_en` = COALESCE(NULLIF(`answer_en`, ''), 'AEG offers unlimited insurance coverage limits, subject to the applicable policy terms and conditions. This means eligible goods can be insured without a fixed overall limit on their total value.') WHERE `id` = 17; -- วงเงินประกันสูงสุดเท่าไหร่
