UPDATE `chatbot_service_faqs` SET `question_en` = COALESCE(NULLIF(`question_en`, ''), 'What additional facilities and services are available with AEG''s safety deposit Locker rental service?'), `answer_en` = COALESCE(NULLIF(`answer_en`, ''), 'To provide a comprehensive safe deposit box rental experience, we offer the following additional facilities and services:
