UPDATE `chatbot_service_faqs` SET `question_en` = COALESCE(NULLIF(`question_en`, ''), 'How long will I have to wait for a AEG technician after booking an appointment?'), `answer_en` = COALESCE(NULLIF(`answer_en`, ''), 'If you book through our application, the technician will arrive at the scheduled time. If you make an appointment by phone, the technician will arrive at the time confirmed during the call. If there are any changes to the schedule, our team will contact you.') WHERE `id` = 26; -- ต้องรอช่างนานแค่ไหนหลังจากทำการนัดหมาย?
